function evidence = f90_xbatt04_extract_reference_evidence( ...
        modelPath, outputDir, officialScenarios, evaluatorAssetRoot)
%F90_XBATT04_EXTRACT_REFERENCE_EVIDENCE Replay the exact current reference.
arguments
    modelPath (1,1) string
    outputDir (1,1) string
    officialScenarios (1,1) string
    evaluatorAssetRoot (1,1) string
end

assert(isfile(modelPath), "SimuVerity:F90:XBATT04:ModelMissing", ...
    "Reference model is missing: %s", modelPath);
assert(isfile(officialScenarios), "SimuVerity:F90:XBATT04:OfficialScenarios", ...
    "Official scenarios are missing: %s", officialScenarios);
assert(isfolder(evaluatorAssetRoot), "SimuVerity:F90:XBATT04:ReferenceAssetRoot", ...
    "Evaluator-owned reference asset root is missing: %s", evaluatorAssetRoot);

expectedPresence = lower(strtrim(string("present")));
assert(strlength(expectedPresence) > 0, "SimuVerity:F90:XBATT04:ReferenceBinding", ...
    "The evaluator reference file presence binding is missing or invalid.");
assert(localFilePresence(modelPath) == expectedPresence, ...
    "SimuVerity:F90:XBATT04:ReferenceIdentity", ...
    "Reference file presence differs from the task binding.");

referenceRoot = fullfile(evaluatorAssetRoot, "Simscape-Battery-Library");
localValidateReferenceClosure(referenceRoot, expectedPresence);
official = localOfficialScenarios(officialScenarios);

assert(~isfolder(outputDir), "SimuVerity:F90:XBATT04:OutputReuse", ...
    "Reference evidence output directory already exists: %s", outputDir);
mkdir(outputDir);
cacheDir = fullfile(outputDir, "cache");
codegenDir = fullfile(outputDir, "codegen");
mkdir(cacheDir);
mkdir(codegenDir);
Simulink.fileGenControl("set", "CacheFolder", cacheDir, ...
    "CodeGenFolder", codegenDir, "createDir", true);
set(groot, "defaultFigureVisible", "off");
addpath(genpath(referenceRoot), "-begin");

generationRunId = string(getenv("SIMUVERITY_GENERATION_RUN_ID"));
scoringRunId = string(getenv("SIMUVERITY_SCORING_RUN_ID"));
assert(strlength(generationRunId) > 0, "SimuVerity:F90:XBATT04:GenerationRunId", ...
    "SIMUVERITY_GENERATION_RUN_ID is required.");
assert(strlength(scoringRunId) > 0, "SimuVerity:F90:XBATT04:ScoringRunId", ...
    "SIMUVERITY_SCORING_RUN_ID is required.");

evidencePath = fullfile(outputDir, "evidence.json");
sourcePresenceBefore = localFilePresence(modelPath);
evidence = struct( ...
    "schema", "simuverity.f90-xbatt04-evidence.v1", ...
    "task_id", "F90-XBATT-04", ...
    "evaluation_subject", "reference", ...
    "reference_identity_applicable", true, ...
    "source_model", modelPath, ...
    "source_model_file_presence", sourcePresenceBefore, ...
    "reference_substantive_modifications", 0, ...
    "extraction_only", true, ...
    "contains_score_decisions", false, ...
    "load_pass", false, ...
    "update_pass", false, ...
    "compile_pass", false, ...
    "nominal_smoke_pass", false, ...
    "static_audit", struct, ...
    "scenarios", struct([]), ...
    "errors", struct, ...
    "model_closed_without_save", false, ...
    "reference_binding_preserved", false, ...
    "EVIDENCE_COMPLETE", false, ...
    "evidence_complete", false, ...
    "started_at", localNow, ...
    "runtime", struct( ...
        "generation_run_id", generationRunId, ...
        "scoring_run_id", scoringRunId, ...
        "matlab_release", string(version("-release")), ...
        "matlab_prefdir", string(getenv("MATLAB_PREFDIR")), ...
        "cache", cacheDir, ...
        "codegen", codegenDir));
localWriteJson(evidencePath, evidence);

model = "";
try
    modelHandle = load_system(modelPath);
    model = string(get_param(modelHandle, "Name"));
    assert(model == "TSPMeA_Cycling", "SimuVerity:F90:XBATT04:ReferenceModelName", ...
        "Unexpected reference model name: %s", model);
    evidence.load_pass = true;

    set_param(model, "SimscapeUseOperatingPoints", "off");
    evalin("base", "clear op");
    localInstallMeasurementTaps(model);
    set_param(model, ...
        "ReturnWorkspaceOutputs", "on", ...
        "StopTime", "50E6", ...
        "SaveState", "on", ...
        "StateSaveName", "xout", ...
        "SignalLogging", "on", ...
        "SignalLoggingName", "logsout", ...
        "SimscapeLogType", "all", ...
        "SimscapeLogLimitData", "off");
    localApplyScenario(model, official.scenarios(1), 1);
    set_param(model, "SimulationCommand", "update");
    evidence.update_pass = true;
    feval(model, [], [], [], "compile");
    feval(model, [], [], [], "term");
    evidence.compile_pass = true;
    evidence.static_audit = localStaticAudit(model);
    localWriteJson(evidencePath, evidence);

    smoke = sim(model, "ReturnWorkspaceOutputs", "on");
    localValidateSmoke(smoke);
    evidence.nominal_smoke_pass = true;
    clear smoke

    rows = repmat(localEmptyScenario, numel(official.scenarios), 1);
    for k = 1:numel(official.scenarios)
        scenario = official.scenarios(k);
        rows(k).id = string(scenario.id);
        rows(k).requested_inputs = scenario;
        try
            set_param(model, "SimscapeUseOperatingPoints", "off");
            evalin("base", "clear op");
            localApplyScenario(model, scenario, ...
                double(scenario.number_of_cycles));
            started = tic;
            simOut = sim(model, "ReturnWorkspaceOutputs", "on");
            rows(k).simulation_wall_clock_s = toc(started);
            outputs = localExtractOutputs(simOut);
            rows(k) = localFinalizeScenario(rows(k), outputs, ...
                double(scenario.number_of_cycles));
            clear simOut
        catch ME
            rows(k).error = localError(ME);
        end
        evidence.scenarios = rows;
        localWriteJson(evidencePath, evidence);
    end

    assert(all([rows.valid]), "SimuVerity:F90:XBATT04:ScenarioEvidence", ...
        "One or more fixed reference scenarios did not produce valid evidence.");
    localCloseModel(model);
    evidence.model_closed_without_save = ~bdIsLoaded(model);
    evidence.reference_binding_preserved = ...
        localFilePresence(modelPath) == sourcePresenceBefore;
    assert(evidence.reference_binding_preserved, ...
        "SimuVerity:F90:XBATT04:ReferenceModified", ...
        "Reference extraction modified the current model file.");
    evidence.EVIDENCE_COMPLETE = evidence.load_pass && ...
        evidence.update_pass && evidence.compile_pass && ...
        evidence.nominal_smoke_pass && ...
        evidence.static_audit.core_path_qualified && ...
        all([evidence.scenarios.valid]) && ...
        evidence.model_closed_without_save && ...
        evidence.reference_binding_preserved;
    evidence.evidence_complete = evidence.EVIDENCE_COMPLETE;
    assert(evidence.EVIDENCE_COMPLETE, "SimuVerity:F90:XBATT04:EvidenceIncomplete", ...
        "Reference extraction did not satisfy the evidence-lock prerequisites.");
    evidence.finished_at = localNow;
    localWriteJson(evidencePath, evidence);
catch ME
    try
        if strlength(model) > 0
            feval(model, [], [], [], "term");
        end
    catch
    end
    localCloseModel(model);
    evidence.model_closed_without_save = ...
        strlength(model) == 0 || ~bdIsLoaded(model);
    evidence.reference_binding_preserved = ...
        localFilePresence(modelPath) == sourcePresenceBefore;
    evidence.EVIDENCE_COMPLETE = false;
    evidence.evidence_complete = false;
    evidence.errors.session = localError(ME);
    evidence.finished_at = localNow;
    localWriteJson(evidencePath, evidence);
    rethrow(ME)
end

fprintf("F90_XBATT04_REFERENCE_EVIDENCE load=%d update=%d compile=%d smoke=%d valid=%d/%d complete=%d path=%s\n", ...
    evidence.load_pass, evidence.update_pass, evidence.compile_pass, ...
    evidence.nominal_smoke_pass, sum([evidence.scenarios.valid]), ...
    numel(evidence.scenarios), evidence.EVIDENCE_COMPLETE, evidencePath);
end

function official = localOfficialScenarios(pathValue)
official = jsondecode(fileread(pathValue));
assert(isstruct(official) && isfield(official, "schema") && ...
    string(official.schema) == "simuverity.official-scenarios.v1", ...
    "SimuVerity:F90:XBATT04:ScenarioSchema", ...
    "Unexpected official scenario schema.");
assert(isfield(official, "task_id") && ...
    string(official.task_id) == "F90-XBATT-04", ...
    "SimuVerity:F90:XBATT04:ScenarioTask", ...
    "Official scenarios are bound to a different task.");
assert(isfield(official, "scenarios") && isstruct(official.scenarios), ...
    "SimuVerity:F90:XBATT04:ScenarioRows", ...
    "Official scenario rows are missing.");
expectedIds = ["nominal", "cold_charge", "warm_cycle", ...
    "higher_charge_rate", "lower_upper_cutoff", ...
    "raised_lower_cutoff", "moderate_cold_rate"];
actualIds = string({official.scenarios.id});
assert(isequal(actualIds(:).', expectedIds), ...
    "SimuVerity:F90:XBATT04:ScenarioContract", ...
    "Official scenario IDs or order differ from the task binding.");
requiredFields = ["Vmax", "Vmin", "Ic", "Id", ...
    "ambient_temperature_K", "initial_temperature_K", ...
    "number_of_cycles"];
for k = 1:numel(official.scenarios)
    row = official.scenarios(k);
    for name = requiredFields
        assert(isfield(row, name) && isscalar(row.(name)) && ...
            isfinite(double(row.(name))), ...
            "SimuVerity:F90:XBATT04:ScenarioInput", ...
            "Scenario %s has an invalid %s input.", string(row.id), name);
    end
end
end

function localValidateReferenceClosure(referenceRoot, expectedPresence)
assert(isfolder(referenceRoot), "SimuVerity:F90:XBATT04:ReferenceClosure", ...
    "Reference dependency root is missing: %s", referenceRoot);
required = [ ...
    fullfile(referenceRoot, "Examples", "viaMatlabCode", ...
        "TSPMeA_Cycling.slx"), ...
    fullfile(referenceRoot, "+BatteryLibrary", "+Models", ...
        "TSPMeA.ssc"), ...
    fullfile(referenceRoot, "+BatteryLibrary", "+Utilities", ...
        "BatteryCycler.ssc")];
for pathValue = required
    assert(isfile(pathValue), "SimuVerity:F90:XBATT04:ReferenceIncomplete", ...
        "Reference dependency is missing: %s", pathValue);
end
assert(localFilePresence(required(1)) == expectedPresence, ...
    "SimuVerity:F90:XBATT04:ReferenceClosureIdentity", ...
    "Evaluator asset closure contains a different reference model.");
end

function localInstallMeasurementTaps(model)
scope = model + "/Scope";
localTap(scope, scope + "/From", "f90_current_A");
localTap(scope, scope + "/From1", "f90_voltage_V");
localTap(scope, scope + "/From2", "f90_temperature_K");
localTap(scope, scope + "/From3", "f90_soc");
localTap(scope, scope + "/From4", "f90_potentials_V");
localTap(scope, scope + "/From5", "f90_film_um");
localTap(scope, scope + "/From6", "f90_soh");
localTap(scope, scope + "/From7", "f90_capacity_losses");
localTap(scope, scope + "/From8", "f90_porosity");
localTap(model, model + "/Subsystem", "f90_cycle_count");
end

function localTap(parent, source, variable)
tap = parent + "/F90 " + variable + " Tap";
assert(getSimulinkBlockHandle(tap) < 0, ...
    "SimuVerity:F90:XBATT04:TapCollision", ...
    "Temporary measurement tap already exists.");
add_block("simulink/Sinks/To Workspace", tap, ...
    "VariableName", variable, ...
    "SaveFormat", "Timeseries", ...
    "MaxDataPoints", "inf");
sourcePorts = get_param(source, "PortHandles");
tapPorts = get_param(tap, "PortHandles");
assert(sourcePorts.Outport(1) > 0 && tapPorts.Inport(1) > 0, ...
    "SimuVerity:F90:XBATT04:TapPort", "A required real source port is missing.");
add_line(parent, sourcePorts.Outport(1), tapPorts.Inport(1), ...
    "autorouting", "on");
end

function localApplyScenario(model, scenario, cycles)
assignin("base", "number_of_cycles", cycles);
for name = ["Vmax", "Vmin", "Ic", "Id", ...
        "ambient_temperature_K", "initial_temperature_K"]
    assignin("base", name, double(scenario.(name)));
end
set_param(model + "/Simple cycler", ...
    "Vmax", sprintf("%.17g", double(scenario.Vmax)), ...
    "Vmin", sprintf("%.17g", double(scenario.Vmin)), ...
    "Ic", sprintf("%.17g", double(scenario.Ic)), ...
    "Id", sprintf("%.17g", double(scenario.Id)));
localSetPhysicalParameter(model + "/Temperature Source", ...
    "temperature", double(scenario.ambient_temperature_K), "K");
localSetPhysicalParameter(model + "/TSPMeA", ...
    "T0", double(scenario.initial_temperature_K), "K");
end

function localSetPhysicalParameter(block, parameter, value, unit)
set_param(block, parameter, sprintf("%.17g", value));
unitParameter = parameter + "_unit";
dialog = get_param(block, "DialogParameters");
if isfield(dialog, char(unitParameter))
    set_param(block, unitParameter, unit);
end
end

function localValidateSmoke(simOut)
names = ["f90_current_A", "f90_voltage_V", "f90_temperature_K", ...
    "f90_soc", "f90_potentials_V", "f90_film_um", "f90_soh", ...
    "f90_capacity_losses", "f90_porosity", "f90_cycle_count"];
for name = names
    value = localGetOutput(simOut, name);
    assert(isa(value, "timeseries") && numel(value.Time) >= 2, ...
        "SimuVerity:F90:XBATT04:SmokeTap", ...
        "Smoke run did not produce required Timeseries %s.", name);
end
end

function outputs = localExtractOutputs(simOut)
current = localTimeseriesMatrix(simOut, "f90_current_A", 1);
voltage = localTimeseriesMatrix(simOut, "f90_voltage_V", 1);
temperature = localTimeseriesMatrix(simOut, "f90_temperature_K", 1);
soc = localTimeseriesMatrix(simOut, "f90_soc", 1);
potentials = localTimeseriesMatrix(simOut, "f90_potentials_V", 3);
film = localTimeseriesMatrix(simOut, "f90_film_um", 1);
soh = localTimeseriesMatrix(simOut, "f90_soh", 1);
losses = localTimeseriesMatrix(simOut, "f90_capacity_losses", 2);
porosity = localTimeseriesMatrix(simOut, "f90_porosity", 1);
cycle = localTimeseriesMatrix(simOut, "f90_cycle_count", 1);

startTime = max([current.time(1), voltage.time(1), temperature.time(1), ...
    soc.time(1), potentials.time(1), film.time(1), soh.time(1), ...
    losses.time(1), porosity.time(1), cycle.time(1)]);
endTime = min([current.time(end), voltage.time(end), temperature.time(end), ...
    soc.time(end), potentials.time(end), film.time(end), soh.time(end), ...
    losses.time(end), porosity.time(end), cycle.time(end)]);
assert(endTime > startTime, "SimuVerity:F90:XBATT04:EvidenceOverlap", ...
    "Required physical signals have no common time interval.");
time = linspace(startTime, endTime, 4000)';
outputs = struct( ...
    "time_s", time, ...
    "electrical_state", [ ...
        localInterp(voltage, time, "linear"), ...
        localInterp(current, time, "previous"), ...
        localInterp(temperature, time, "linear"), ...
        localInterp(cycle, time, "previous")], ...
    "electrochemical_state", [ ...
        localInterp(soc, time, "linear"), ...
        localInterp(potentials, time, "linear")], ...
    "ageing_state", [ ...
        localInterp(film, time, "linear"), ...
        localInterp(porosity, time, "linear"), ...
        localInterp(soh, time, "linear"), ...
        localInterp(losses, time, "linear")], ...
    "native_sample_counts", struct( ...
        "current", size(current.values, 1), ...
        "voltage", size(voltage.values, 1), ...
        "temperature", size(temperature.values, 1), ...
        "soc", size(soc.values, 1), ...
        "potentials", size(potentials.values, 1), ...
        "film", size(film.values, 1), ...
        "soh", size(soh.values, 1), ...
        "losses", size(losses.values, 1), ...
        "porosity", size(porosity.values, 1), ...
        "cycle", size(cycle.values, 1)));
end

function series = localTimeseriesMatrix(simOut, name, channels)
value = localGetOutput(simOut, name);
assert(isa(value, "timeseries"), "SimuVerity:F90:XBATT04:WorkspaceTap", ...
    "Required measurement tap %s is missing.", name);
time = double(value.Time(:));
data = squeeze(double(value.Data));
if isvector(data)
    data = data(:);
elseif size(data, 1) ~= numel(time) && size(data, 2) == numel(time)
    data = data.';
end
assert(size(data, 1) == numel(time) && size(data, 2) == channels, ...
    "SimuVerity:F90:XBATT04:TapShape", ...
    "Unexpected shape for %s: expected %d channels.", name, channels);
[time, uniqueIndex] = unique(time, "stable");
data = data(uniqueIndex, :);
series = struct("time", time, "values", data);
end

function values = localInterp(series, time, method)
values = interp1(series.time, series.values, time, method, "extrap");
if isvector(values), values = values(:); end
end

function row = localFinalizeScenario(row, outputs, expectedCycles)
allValues = [outputs.time_s; outputs.electrical_state(:); ...
    outputs.electrochemical_state(:); outputs.ageing_state(:)];
row.simulation_pass = true;
row.required_evidence_pass = ...
    all(isfinite(allValues)) && ...
    numel(outputs.time_s) == 4000 && ...
    outputs.time_s(1) == 0 && ...
    max(outputs.electrical_state(:,4)) >= expectedCycles - 1;
row.valid = row.required_evidence_pass;
row.sample_count = numel(outputs.time_s);
row.start_time_s = outputs.time_s(1);
row.end_time_s = outputs.time_s(end);
row.completed_cycle_count = max(outputs.electrical_state(:,4));
row.outputs = outputs;
row.error = struct;
end

function audit = localStaticAudit(model)
audit = struct( ...
    "cell_component_path", string(get_param( ...
        model + "/TSPMeA", "ComponentPath")), ...
    "cycler_component_path", string(get_param( ...
        model + "/Simple cycler", "ComponentPath")), ...
    "convective_heat_transfer_present", ...
        getSimulinkBlockHandle(model + "/Convective Heat" + ...
            newline + "Transfer") > 0, ...
    "temperature_source_present", ...
        getSimulinkBlockHandle(model + "/Temperature Source") > 0, ...
    "current_sensor_present", ...
        getSimulinkBlockHandle(model + ...
            "/ampMeter/Current Sensor") > 0, ...
    "voltage_sensor_present", ...
        getSimulinkBlockHandle(model + ...
            "/voltMeter/Voltage Sensor") > 0, ...
    "temperature_sensor_present", ...
        getSimulinkBlockHandle(model + ...
            "/tempSensor/Temperature Sensor") > 0);
audit.cell_component_qualified = ...
    audit.cell_component_path == "BatteryLibrary.Models.TSPMeA";
audit.cycler_component_qualified = ...
    audit.cycler_component_path == "BatteryLibrary.Utilities.BatteryCycler";
audit.thermal_path_qualified = ...
    audit.convective_heat_transfer_present && ...
    audit.temperature_source_present && ...
    audit.temperature_sensor_present;
audit.real_measurements_qualified = ...
    audit.current_sensor_present && ...
    audit.voltage_sensor_present && ...
    audit.temperature_sensor_present;
audit.core_path_qualified = ...
    audit.cell_component_qualified && ...
    audit.cycler_component_qualified && ...
    audit.thermal_path_qualified && ...
    audit.real_measurements_qualified;
end

function value = localGetOutput(simOut, name)
value = [];
try, value = simOut.get(name); catch, end
if isempty(value)
    try, value = evalin("base", name); catch, end
end
end

function row = localEmptyScenario
row = struct( ...
    "id", "", ...
    "requested_inputs", struct, ...
    "simulation_pass", false, ...
    "required_evidence_pass", false, ...
    "valid", false, ...
    "simulation_wall_clock_s", 0, ...
    "sample_count", 0, ...
    "start_time_s", 0, ...
    "end_time_s", 0, ...
    "completed_cycle_count", 0, ...
    "outputs", struct, ...
    "error", struct);
end

function info = localError(ME)
info = struct("identifier", string(ME.identifier), ...
    "message", string(ME.message));
end

function localCloseModel(model)
try
    if strlength(model) > 0 && bdIsLoaded(model)
        close_system(model, 0);
    end
catch
end
end

function binding = localFilePresence(pathValue)
assert(isfile(pathValue), "SimuVerity:FileMissing", "Required file is missing: %s", pathValue);
binding = "present";
end

function localWriteJson(pathValue, value)
fid = fopen(pathValue, "w");
assert(fid > 0, "SimuVerity:F90:XBATT04:JsonWrite", ...
    "Could not open JSON output: %s", pathValue);
cleanup = onCleanup(@() fclose(fid)); %#ok<NASGU>
fwrite(fid, jsonencode(value, PrettyPrint=true), "char");
end

function value = localNow
value = string(datetime("now", ...
    "TimeZone", "Asia/Shanghai", ...
    "Format", "yyyy-MM-dd'T'HH:mm:ssXXX"));
end
